<?php require_once 'functions.php'; $id=(int)($_GET['id']??0); $s=$koneksi->prepare('SELECT p.*,k.nama_kategori FROM produk p LEFT JOIN kategori k ON k.id_kategori=p.id_kategori WHERE p.id_produk=?'); $s->bind_param('i',$id); $s->execute(); $p=$s->get_result()->fetch_assoc(); if(!$p){flash('error','Produk tidak ditemukan.');redirect('produk.php');} $title=$p['nama_produk'];
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$qty=max(1,(int)$_POST['jumlah']);if($p['stok']<1)flash('error','Stok produk habis.');elseif($qty>$p['stok'])flash('error','Jumlah melebihi stok.');else{$_SESSION['keranjang'][$id]=min($p['stok'],(int)($_SESSION['keranjang'][$id]??0)+$qty);flash('success','Produk ditambahkan ke keranjang.');redirect('keranjang.php');}}
include 'header.php'; ?>
<div class="container product-detail"><div class="detail-image"><?= $p['image_url'] ? '<img src="'.e($p['image_url']).'" alt="'.e($p['nama_produk']).'">' : '📦' ?></div><div><span class="pill"><?=e($p['nama_kategori']??'Produk')?></span><h1><?=e($p['nama_produk'])?></h1><h2><?=rupiah($p['harga'])?></h2><p><?=nl2br(e($p['deskripsi']))?></p><p class="muted">Stok tersedia: <?=$p['stok']?></p><?php if($p['stok']>0): ?><form method="post" class="panel compact"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Jumlah</label><input type="number" name="jumlah" value="1" min="1" max="<?=$p['stok']?>"><button class="btn">Tambah ke Keranjang</button></form><?php else:?><div class="alert error">Produk sedang habis.</div><?php endif;?></div></div><?php include 'footer.php'; ?>
